/* One canonical content model feeds the review, search, and framework MDX pages. */
const fs=require('node:fs'),path=require('node:path');require('./register.cjs');
const {articles}=require('../lib/content.ts');const out=path.resolve(__dirname,'../content/docs');fs.mkdirSync(out,{recursive:true});
const xml=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/{/g,'&#123;').replace(/}/g,'&#125;');
for(const article of articles){let body=`---\ntitle: ${JSON.stringify(article.title)}\ndescription: ${JSON.stringify(article.description)}\n---\n\n{/* Generated by scripts/generate-mdx.cjs; edit lib/content.ts instead. */}\n\n`;
for(const section of article.sections){body+=`<section className="article-section">\n\n<h2 id="${section.id}"><a href="#${section.id}">${xml(section.title)}<span className="heading-hash" aria-hidden="true">#</span></a></h2>\n\n`;
for(const paragraph of section.paragraphs)body+=`<p>${xml(paragraph)}</p>\n\n`;
if(section.code)body+=`<CodeBlock code={${JSON.stringify(section.code)}} label="Shell commands" />\n\n`;
if(section.note)body+=`<aside className="callout"><p>${xml(section.note)}</p></aside>\n\n`;
body+='</section>\n\n';}
fs.writeFileSync(path.join(out,(article.slug||'index')+'.mdx'),body)}
fs.writeFileSync(path.join(out,'meta.json'),JSON.stringify({title:'Documentation',pages:articles.map(a=>a.slug||'index')},null,2)+'\n');
console.log(`Generated ${articles.length} MDX documents from canonical typed content. MDX compilation is a separate framework build step.`);
